//! GAFP asset facts: what the real packer wrote, re-read by the crate it was
//! written for (plan of record, item 6b-2).
//!
//! `crates/flac-lite/tests/gafp_asset_vectors.txt` is generated by
//! `scripts/gen_gafp_fixtures.py`, which drives `scripts/gafp_pack.py` — the real
//! GAFP writer — over PCM synthesized by `scripts/frame_vectors.py` and encoded by
//! libFLAC. The `.gfp` files under `tests/gfp/` are the packer's bytes, committed.
//! This suite reads them through the crate's own facade: `Manifest::parse`,
//! `scan::Frames`, `Decoder`. It adds nothing to the format and re-derives nothing
//! the table already states; the point is that three independent readings meet on
//! the same bytes — the packer's walk (Python, strict RFC 9639 headers, its own
//! CRC tables, subframe slot by slot), the crate's walk (Rust), and a reference
//! decoder's audio (`flac -d`) as pinned by FNV-1a-64.
//!
//! What each test is for
//! ---------------------
//! * `the_table_and_its_blobs_are_all_here` — the table is self-consistent and
//!   the files it names are the files that are committed. A packed asset that no
//!   test reads is not a witness, so a blob name this suite does not embed is a
//!   build failure rather than a file nobody looks at.
//! * `the_manifest_says_what_the_packer_recorded` — every header field and every
//!   offset-table entry, read back by `Manifest`, against what the packer wrote.
//! * `the_offset_table_and_a_walk_of_the_region_agree_frame_by_frame` — the
//!   offsets the container hands out are the offsets a decode walk produces. The
//!   offset table is not trusted here; it is compared, and the frame footer
//!   CRC-16s are computed from the bytes the packer put in the region.
//! * `every_blob_decodes_to_the_pcm_the_reference_decoder_produced` — bit-exact
//!   PCM, per frame and whole-stream, against `flac -d`'s output. `PcmPin` is the
//!   same fold `scan_frame_walk_layout.rs` uses, so a pass here means exactly what
//!   a pass means there, including the 16-bit width the pins are made of.
//! * `one_pcm_three_blobs_and_the_field_that_cannot_tell_them_apart` — the 6b-2
//!   witness proper, spelled out below.
//! * `the_refusals_are_on_the_record` — the assets the packer would not write at
//!   the product profile, with the reason it printed. A refusal that does not name
//!   the property is a bug report nobody can act on.
//!
//! The one thing this suite is about
//! --------------------------------
//! `format::EncodeProfile::validate`'s own docs say a manifest cannot answer
//! "does this stream contain LPC subframes" — that fact lives in the subframes,
//! and pack time is where it gets checked. Three of the four blobs here are the
//! same five thousand samples encoded three ways: independent stereo, mid/side, and
//! `-l 4`. All three decode to identical audio, and all three manifests carry
//! `max_fixed_order = 0` — the byte a header-based profile check polices — because
//! an all-LPC stream genuinely has no FIXED subframe of order above zero. So
//! `DEFAULT_PROFILE.validate` accepts the LPC asset, a hand-tightened `-l 0`-shaped
//! profile accepts it too, and `Decoder` plays it correctly. Nothing on this side
//! of the line can tell you that at 32 kHz the decode half of that asset alone
//! costs 174.14% of the frame — 1,816,753 cycles where a 2048-sample frame at the
//! 32768 Hz playback timer has 1,048,576 — against 42.48% for the FIXED-only asset
//! it sits beside.
//!
//! That is not a defect to fix in the decoder; it is why the fixture set exists:
//! to keep honest the claim that C2's "FIXED-only" is enforced at pack time, and to
//! record in data a test reads — not in prose — which guard did the work, what the
//! measured cost was, and which two relaxations it took to write the LPC one
//! anyway (`preflight`, which refuses to build `-l 4` at a rate where the measured
//! row is already over budget, and the post-walk cost bar; one does not imply the
//! other).

#![forbid(unsafe_code)]

use flac_lite::format::{DEFAULT_PROFILE, EncodeProfile, HEADER_LEN};
use flac_lite::scan::Frames;
use flac_lite::{Decoder, FrameBuffers, Manifest, PredictorState};

/// The frame footer, from the crate's own table — `bits::crc16`, the function the
/// encode path fills the footer with and `crc-check` verifies on the decode path.
fn crc16(data: &[u8]) -> u16 {
    flac_lite::bits::crc16(data)
}

const TABLE: &str = include_str!("gafp_asset_vectors.txt");

/// The committed blobs, embedded by name — the only way a blob in the table
/// reaches Rust. A fixture the generator writes and this suite does not embed is
/// a fixture nobody verifies, so it fails loudly instead of sitting there.
fn blob_bytes(name: &str) -> &'static [u8] {
    match name {
        "p0_fixed0_mono_32k_b2048.gfp" => include_bytes!("gfp/p0_fixed0_mono_32k_b2048.gfp"),
        "p2_fixed0_stereo_32k_b2048.gfp" => include_bytes!("gfp/p2_fixed0_stereo_32k_b2048.gfp"),
        "p3_fixed0_midside_32k_b2048.gfp" => include_bytes!("gfp/p3_fixed0_midside_32k_b2048.gfp"),
        "x1_lpc_stereo_32k_b2048.gfp" => include_bytes!("gfp/x1_lpc_stereo_32k_b2048.gfp"),
        other => panic!(
            "the table names a blob this suite does not embed: {other}. Embed it \
             or drop it from the generator — a packed asset no Rust test reads is \
             a file, not a witness."
        ),
    }
}

// --------------------------------------------------------------- the table

/// One `subframe` row: the packer's reading of one subframe slot. Nothing in the
/// crate's public API reports a predictor kind, so this cannot be re-derived on
/// the Rust side — which is precisely the point of the fixture.
#[derive(Debug, Clone)]
struct SlotRow {
    kind: String,
    order: u64,
    entry_bit: u64,
    exit_bit: u64,
}

/// One `frame` row: the packer's walk of one frame, plus the reference decoder's
/// pinned audio for that frame's samples.
#[derive(Debug, Clone)]
struct FrameRow {
    index: u64,
    number: u64,
    blob_offset: u64,
    region_offset: u64,
    bytes: u64,
    blocksize: u64,
    rate: u64,
    subframes: u64,
    bps: u64,
    header_bits: u64,
    exit_bit: u64,
    padded: u64,
    end_bit: u64,
    crc16: u64,
    pcm_fnv: u64,
    pcm_values: u64,
    first: Vec<i64>,
    last: Vec<i64>,
}

/// One block of the table: the packer's `profile`/`relaxations`/`verdict` rows,
/// its `blob` row, and everything it walked to make them.
#[derive(Debug, Clone, Default)]
struct Blob {
    name: String,
    bytes: u64,
    frame_count: u64,
    rate: u64,
    blocksize: u64,
    channels: u64,
    bps: u64,
    max_fixed_order: u64,
    total_samples: u64,
    frame_data: u64,
    pcm_fnv: u64,
    pcm_values: u64,
    pcm_bytes_len: u64,
    pcm_first: Vec<i64>,
    pcm_last: Vec<i64>,
    profile_max_lpc_order: u64,
    allow_lpc: bool,
    allow_over_budget: bool,
    relaxations: String,
    decision: String,
    product: bool,
    frames: Vec<FrameRow>,
    slots: Vec<SlotRow>,
}

/// One `refusal` row: an asset the packer would not write, and what it said.
#[derive(Debug, Clone)]
struct Refusal {
    slug: String,
    exit: u64,
    wrote_file: bool,
    reason: String,
}

/// `key=value` from a data row. Field values never contain a space — the
/// generator asserts that, and the table header documents it — with one
/// deliberate exception, `reason=`, which is always the last field in its row.
///
/// A key is found only as a whole field (a leading space, or the start of the
/// row after the row-type word), so `blocksize=` cannot be satisfied by the
/// `blocksize` inside `frame_blocksize=`.
fn field<'a>(row: &'a str, key: &str) -> &'a str {
    let key_eq = format!("{key}=");
    let at = if row.starts_with(&key_eq) {
        0
    } else {
        let pat = format!(" {key_eq}");
        match row.find(&pat) {
            Some(i) => i + 1,
            None => panic!("row has no `{key}` field: {row}"),
        }
    };
    let rest = &row[at + key_eq.len()..];
    if key == "reason" {
        return rest;
    }
    rest.split(' ').next().unwrap_or("")
}

fn num(row: &str, key: &str) -> u64 {
    field(row, key)
        .parse()
        .unwrap_or_else(|_| panic!("`{key}` is not a number in: {row}"))
}

/// `0x…` as the PCM and CRC pins are written.
fn hex(row: &str, key: &str) -> u64 {
    let raw = field(row, key);
    let digits = raw.strip_prefix("0x").unwrap_or(raw);
    u64::from_str_radix(digits, 16).unwrap_or_else(|_| panic!("`{key}` is not hex in: {row}"))
}

/// Colon-separated sample values, the shape the first/last pins use.
fn vals(row: &str, key: &str) -> Vec<i64> {
    field(row, key)
        .split(':')
        .map(|v| {
            v.parse()
                .unwrap_or_else(|_| panic!("`{key}` holds {v:?} in: {row}"))
        })
        .collect()
}

fn yes(row: &str, key: &str) -> bool {
    match field(row, key) {
        "true" => true,
        "false" => false,
        other => panic!("`{key}` is not true/false ({other:?}) in: {row}"),
    }
}

/// Read the whole table. Blocks are delimited by their `profile` row, which the
/// packer writes first; the `refusal` rows stand alone.
fn load() -> (Vec<Blob>, Vec<Refusal>) {
    let mut blobs: Vec<Blob> = Vec::new();
    let mut refusals: Vec<Refusal> = Vec::new();
    let mut cur: Option<Blob> = None;

    for raw in TABLE.lines() {
        let line = raw.trim_end();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(row) = line.strip_prefix("profile ") {
            if let Some(done) = cur.replace(Blob::default()) {
                blobs.push(done);
            }
            let mut b = Blob::default();
            b.rate = num(row, "rate");
            b.blocksize = num(row, "blocksize");
            b.channels = num(row, "channels");
            b.profile_max_lpc_order = num(row, "max_lpc_order");
            b.allow_lpc = yes(row, "allow_lpc");
            b.allow_over_budget = yes(row, "allow_over_budget");
            cur = Some(b);
            continue;
        }
        if let Some(row) = line.strip_prefix("refusal ") {
            refusals.push(Refusal {
                slug: field(row, "slug").to_string(),
                exit: num(row, "exit"),
                wrote_file: yes(row, "wrote_file"),
                reason: field(row, "reason").to_string(),
            });
            continue;
        }
        let target = cur
            .as_mut()
            .expect("a data row before any `profile` row: the block order broke");
        if let Some(row) = line.strip_prefix("relaxations ") {
            target.relaxations = field(row, "list").to_string();
        } else if let Some(row) = line.strip_prefix("verdict ") {
            target.decision = field(row, "decision").to_string();
            target.product = yes(row, "product");
        } else if let Some(row) = line.strip_prefix("blob ") {
            target.name = field(row, "name").to_string();
            target.bytes = num(row, "bytes");
            target.frame_count = num(row, "frames");
            target.rate = num(row, "rate");
            target.blocksize = num(row, "blocksize");
            target.channels = num(row, "channels");
            target.bps = num(row, "bps");
            target.max_fixed_order = num(row, "max_fixed_order");
            target.total_samples = num(row, "total_samples");
            target.frame_data = num(row, "frame_data");
            target.pcm_fnv = hex(row, "pcm_fnv1a64");
            target.pcm_values = num(row, "pcm_values");
            target.pcm_bytes_len = num(row, "pcm_bytes_len");
            target.pcm_first = vals(row, "pcm_first");
            target.pcm_last = vals(row, "pcm_last");
        } else if let Some(row) = line.strip_prefix("frame ") {
            target.frames.push(FrameRow {
                index: num(row, "index"),
                number: num(row, "number"),
                blob_offset: num(row, "blob_offset"),
                region_offset: num(row, "region_offset"),
                bytes: num(row, "bytes"),
                blocksize: num(row, "blocksize"),
                rate: num(row, "rate"),
                subframes: num(row, "subframes"),
                bps: num(row, "bps"),
                header_bits: num(row, "header_bits"),
                exit_bit: num(row, "exit_bit"),
                padded: num(row, "padded"),
                end_bit: num(row, "end_bit"),
                crc16: hex(row, "crc16"),
                pcm_fnv: hex(row, "pcm_fnv1a64"),
                pcm_values: num(row, "pcm_values"),
                first: vals(row, "pcm_first"),
                last: vals(row, "pcm_last"),
            });
        } else if let Some(row) = line.strip_prefix("subframe ") {
            target.slots.push(SlotRow {
                kind: field(row, "kind").to_string(),
                order: num(row, "order"),
                entry_bit: num(row, "entry_bit"),
                exit_bit: num(row, "exit_bit"),
            });
        } else {
            panic!("unrecognised table row: {line}");
        }
    }
    if let Some(done) = cur {
        blobs.push(done);
    }
    (blobs, refusals)
}

/// Every `# encoder:` line: one in the header, one per block. They must all name
/// the same libFLAC, or the four committed blobs were not made by one run of one
/// encoder — which would quietly invalidate every cross-blob comparison below.
fn encoder_lines() -> Vec<String> {
    TABLE
        .lines()
        .filter_map(|l| l.trim_end().strip_prefix("# encoder: "))
        .map(str::to_string)
        .collect()
}

fn blob_named<'a>(blobs: &'a [Blob], name: &str) -> &'a Blob {
    blobs
        .iter()
        .find(|b| b.name == name)
        .unwrap_or_else(|| panic!("the table has no block for `{name}`"))
}

fn refusal<'a>(refusals: &'a [Refusal], slug: &str) -> &'a Refusal {
    refusals.iter().find(|r| r.slug == slug).unwrap_or_else(|| {
        panic!(
            "no refusal row with slug `{slug}`: the generator \
                                  did not run that leg"
        )
    })
}

/// FNV-1a 64-bit over bytes, the constants the generator and the existing suites
/// use: independent implementations meeting on the same bytes.
fn fnv1a64(state: &mut u64, bytes: &[u8]) {
    for b in bytes {
        *state ^= *b as u64;
        *state = state.wrapping_mul(0x0000_0100_0000_01b3);
    }
}

/// The house `PcmPin` of `scan_frame_walk_layout.rs`: the samples a decode
/// produced, in the order the stream interleaves them, hashed the way the
/// reference decoder's whole-file output was hashed. Copied rather than
/// re-invented, so "it matches" means here what it means there.
struct PcmPin {
    hash: u64,
    values: u64,
}

impl PcmPin {
    fn new() -> Self {
        PcmPin {
            hash: 0xcbf4_3ce9_5de6_84b7,
            values: 0,
        }
    }

    /// Left then (for a frame carrying a second subframe) right, per sample, at
    /// 16-bit little-endian. The width is pinned by the caller against
    /// `pcm_bytes_len = 2 × pcm_values`, and every value is checked to fit, so
    /// this cannot be quietly hashing a different encoding than the pin was made
    /// of.
    fn push(&mut self, stereo: bool, left: &[i32], right: &[i32]) {
        for i in 0..left.len() {
            let l = left[i];
            assert_eq!(
                i64::from(i16::try_from(l).expect("a 16-bit asset outside i16")),
                l as i64,
                "a 16-bit asset decoded a sample that does not fit 16 bits: {l}"
            );
            fnv1a64(&mut self.hash, &l.to_le_bytes()[..2]);
            self.values += 1;
            if stereo {
                let r = right[i];
                assert_eq!(
                    i64::from(i16::try_from(r).expect("a 16-bit asset outside i16")),
                    r as i64,
                    "a 16-bit asset decoded a sample that does not fit 16 bits: {r}"
                );
                fnv1a64(&mut self.hash, &r.to_le_bytes()[..2]);
                self.values += 1;
            }
        }
    }
}

/// A whole blob's audio, interleaved in stream order, as `i16` values — enough
/// to compare two encodings of one PCM sample for sample.
fn decoded_pcm(name: &str) -> Vec<i16> {
    let bytes = blob_bytes(name);
    let m = Manifest::parse(bytes).expect("the packer's blob parses");
    let len = FrameBuffers::required_len(&m);
    let mut left = vec![0i32; len];
    let mut right = vec![0i32; len];
    let mut bufs = FrameBuffers::new(&mut left, &mut right);
    let mut decoder = Decoder::new(&m).expect("the product path's decoder");
    let mut out: Vec<i16> = Vec::new();
    while let Some(frame) = decoder.decode_next(&mut bufs).expect("decode") {
        let stereo = !frame.right.is_empty();
        for i in 0..frame.left.len() {
            out.push(i16::try_from(frame.left[i]).expect("16-bit"));
            if stereo {
                out.push(i16::try_from(frame.right[i]).expect("16-bit"));
            }
        }
    }
    out
}

// ---------------------------------------------------------------- the tests

#[test]
fn the_table_and_its_blobs_are_all_here() {
    let (blobs, refusals) = load();
    assert_eq!(blobs.len(), 4, "the committed fixture set");
    assert_eq!(
        refusals.len(),
        3,
        "the refusal legs: `-l 4` at the product profile, 44.1 kHz at a 32 kHz \
         target, 8-bit at a 16-bit profile"
    );

    let encoders = encoder_lines();
    assert!(!encoders.is_empty(), "no `# encoder:` line anywhere");
    assert!(
        encoders.windows(2).all(|w| w[0] == w[1]),
        "the four blobs were not made by one libFLAC: {encoders:?}"
    );

    for b in &blobs {
        assert_eq!(
            blob_bytes(&b.name).len() as u64,
            b.bytes,
            "{}: the committed file is not the length the table pins",
            b.name
        );
        assert_eq!(
            b.frames.len() as u64,
            b.frame_count,
            "{}: the table's frame rows do not match its own count",
            b.name
        );
        assert_eq!(
            b.frame_data,
            (HEADER_LEN + 4 * b.frames.len()) as u64,
            "{}: the frame data does not begin where the table says",
            b.name
        );

        // The table's own arithmetic: header + offset table + frames, with
        // nothing between them and nothing after the last one.
        let framed: u64 = b.frames.iter().map(|f| f.bytes).sum();
        assert_eq!(
            b.frame_data + framed,
            b.bytes,
            "{}: header + offset table + frames is not the whole file",
            b.name
        );
        assert_eq!(
            b.frames[0].region_offset, 0,
            "{}: the region does not start at its first frame",
            b.name
        );
        let mut cursor = 0u64;
        for (i, f) in b.frames.iter().enumerate() {
            assert_eq!(f.index, i as u64, "frame rows out of order");
            assert_eq!(f.number, i as u64, "{}: the frame numbers", b.name);
            assert_eq!(f.region_offset, cursor, "{}: gap or overlap", b.name);
            assert_eq!(
                f.blob_offset,
                b.frame_data + f.region_offset,
                "{}: the offset table's entries",
                b.name
            );
            cursor += f.bytes;
        }
        assert_eq!(cursor, framed, "{}: the last frame's extent", b.name);

        // Samples: the frames' own block sizes are what the totals mean. Note
        // the last frame is short — 904 of 2048 — which is normal and is part of
        // what these fixtures exist to cover.
        let samples: u64 = b.frames.iter().map(|f| f.blocksize).sum();
        assert_eq!(samples, b.total_samples, "{}: the sample totals", b.name);
        assert_eq!(
            b.pcm_values,
            samples * b.channels,
            "{}: the interleaved sample count",
            b.name
        );
        assert_eq!(
            b.pcm_bytes_len,
            2 * b.pcm_values,
            "{}: the PCM pins are 16-bit, and `PcmPin`'s fold depends on that",
            b.name
        );
        for f in &b.frames {
            assert_eq!(
                f.pcm_values,
                f.blocksize * f.subframes,
                "{}: frame {} ({}) sample count",
                b.name,
                f.index,
                f.number
            );
            assert_eq!(f.subframes, b.channels, "{}: slots per frame", b.name);
            assert_eq!(f.bps, b.bps, "{}: a frame at a different depth", b.name);
            assert_eq!(f.rate, b.rate, "{}: a frame at a different rate", b.name);
        }
        assert_eq!(
            b.slots.len() as u64,
            b.frames.iter().map(|f| f.subframes).sum::<u64>(),
            "{}: the subframe walk does not cover every slot of every frame",
            b.name
        );
    }
}

#[test]
fn the_bit_positions_start_and_end_where_the_headers_and_footer_say() {
    let (blobs, _) = load();
    for b in &blobs {
        let mut slot = 0usize;
        for f in &b.frames {
            // `entry_bit`/`exit_bit`/`padded`/`end_bit` are absolute source-file
            // bit positions (metadata included), so the frame's start bit is
            // recovered by subtracting its byte length. This is the assertion
            // that would have caught the first version's `b.pos - 7`, which was
            // recorded after the warm-up skip and was not the subframe start.
            let frame_start_bit = f.end_bit - f.bytes * 8;
            let first = &b.slots[slot];
            assert_eq!(
                first.entry_bit,
                frame_start_bit + f.header_bits,
                "{}: frame {} slot 0 starts at bit {}, not frame_start+header",
                b.name,
                f.index,
                first.entry_bit
            );
            let mut previous_exit = first.exit_bit;
            for j in 0..f.subframes as usize {
                let s = &b.slots[slot + j];
                if j > 0 {
                    assert_eq!(
                        s.entry_bit, previous_exit,
                        "{}: frame {} slot {j} does not begin where the previous slot ended",
                        b.name, f.index
                    );
                }
                assert!(
                    s.exit_bit >= s.entry_bit,
                    "{}: frame {} slot {j} has a negative extent",
                    b.name,
                    f.index
                );
                previous_exit = s.exit_bit;
            }
            assert_eq!(
                previous_exit, f.exit_bit,
                "{}: frame {} exit_bit is not its last slot's exit",
                b.name, f.index
            );
            let want_padded = f.exit_bit + (8 - f.exit_bit % 8) % 8;
            assert_eq!(
                f.padded, want_padded,
                "{}: frame {} is not byte-padded from its last subframe bit",
                b.name, f.index
            );
            assert_eq!(
                f.end_bit - f.padded,
                16,
                "{}: frame {} is not padded-to-byte + 16-bit footer",
                b.name,
                f.index
            );
            slot += f.subframes as usize;
        }
        assert_eq!(slot, b.slots.len(), "{}: slot cursor", b.name);
    }
}

#[test]
fn the_manifest_says_what_the_packer_recorded() {
    let (blobs, _) = load();
    for b in &blobs {
        let bytes = blob_bytes(&b.name);
        let m = Manifest::parse(bytes)
            .unwrap_or_else(|e| panic!("{}: the packer's own blob will not parse: {e:?}", b.name));
        assert_eq!(m.channels() as u64, b.channels, "{}: channels", b.name);
        assert_eq!(
            u64::from(m.bits_per_sample()),
            b.bps,
            "{}: bits per sample",
            b.name
        );
        assert_eq!(
            u64::from(m.blocksize()),
            b.blocksize,
            "{}: block size",
            b.name
        );
        assert_eq!(
            u64::from(m.sample_rate_hz()),
            b.rate,
            "{}: sample rate",
            b.name
        );
        assert_eq!(
            m.total_samples(),
            b.total_samples,
            "{}: total samples",
            b.name
        );
        assert_eq!(
            m.frame_count() as u64,
            b.frame_count,
            "{}: frame count",
            b.name
        );
        assert_eq!(
            u64::from(m.max_fixed_order()),
            b.max_fixed_order,
            "{}: the recorded max FIXED order",
            b.name
        );
        assert_eq!(
            m.frame_data_start() as u64,
            b.frame_data,
            "{}: where the frames begin",
            b.name
        );
        let defaults = m.stream_defaults();
        assert_eq!(
            u64::from(defaults.sample_rate_hz),
            b.rate,
            "{}: the defaults the facade hands a caller",
            b.name
        );
        assert_eq!(
            u64::from(defaults.bits_per_sample),
            b.bps,
            "{}: the defaults' bit depth",
            b.name
        );

        // The offset table, entry by entry, pointing at real frame syncs.
        let mut covered = 0u64;
        for (i, f) in b.frames.iter().enumerate() {
            assert_eq!(
                m.frame_offset(i).expect("in range") as u64,
                f.blob_offset,
                "{}: offset table entry {i}",
                b.name
            );
            let slice = m.frame_bytes(i).expect("in range");
            assert_eq!(slice.len() as u64, f.bytes, "{}: the extent of {i}", b.name);
            // The entry points at a frame, not at bytes that merely sit where a
            // frame should be: the 14-bit sync `frame.rs` defines (RFC 9639
            // §9.1 — `0b11111111111110`; the blocking strategy is the 16th bit,
            // not part of the sync) is here.
            let lead = u16::from_be_bytes([slice[0], slice[1]]);
            assert_eq!(
                lead >> 2,
                0x3FFE,
                "{}: offset table entry {i} does not point at a frame sync",
                b.name
            );
            covered += f.bytes;
        }
        assert_eq!(
            m.frame_region().len() as u64,
            covered,
            "{}: the region the facade hands a caller is not the frames",
            b.name
        );
        assert_eq!(
            (m.frame_data_start() + m.frame_region().len()) as u64,
            b.bytes,
            "{}: there are bytes after the last frame",
            b.name
        );
    }
}

#[test]
fn the_offset_table_and_a_walk_of_the_region_agree_frame_by_frame() {
    let (blobs, _) = load();
    for b in &blobs {
        let bytes = blob_bytes(&b.name);
        let m = Manifest::parse(bytes).expect("parses");
        // The walk the facade is a shell over, run directly over what the
        // manifest hands out: the region, the defaults, the bounds.
        let region = m.frame_region();
        let mut walk = Frames::region(region, &m.stream_defaults(), m.bounds());
        let cap = usize::try_from(b.blocksize).expect("a sane declared block size");
        let mut left = vec![0i32; cap];
        let mut right = vec![0i32; cap];
        let mut state = [PredictorState::new(); 2];

        for (i, f) in b.frames.iter().enumerate() {
            let got = walk
                .next_frame(&mut left, &mut right, &mut state)
                .expect("walk")
                .unwrap_or_else(|| panic!("{}: the walk stopped at frame {i}", b.name));
            // The table's offsets are not trusted: they are compared with where a
            // strict walk actually landed, and with what the frame itself says.
            assert_eq!(
                got.offset as u64, f.region_offset,
                "{}: the walk found frame {i} somewhere other than the offset \
                 table's entry for it",
                b.name
            );
            assert_eq!(
                got.bytes as u64, f.bytes,
                "{}: frame {i} is a different length than the table's entry said",
                b.name
            );
            assert_eq!(
                got.samples as u64, f.blocksize,
                "{}: frame {i} is not the frame the table's entry described",
                b.name
            );
            assert_eq!(
                u64::from(got.header.number),
                f.number,
                "{}: frame {i}'s own number in its header",
                b.name
            );
            assert_eq!(
                got.header.blocksize as u64, f.blocksize,
                "{}: frame {i}'s own block size in its header",
                b.name
            );
            assert_eq!(
                got.header.channels.subframe_count() as u64,
                f.subframes,
                "{}: frame {i}'s own subframe count",
                b.name
            );
            // The footer, computed here over the bytes the packer put into the
            // region, against the CRC the packer recorded: this is what makes the
            // region's bytes provably the frames that went in. (`crc-check`
            // makes the decode path verify frame CRCs too; nothing here depends
            // on that feature.)
            let at = usize::try_from(f.region_offset).expect("an in-range offset");
            let slice = &region[at..at + usize::try_from(f.bytes).expect("an in-range length")];
            let (body, crc) = slice.split_at(slice.len() - 2);
            assert_eq!(
                u64::from(crc16(body)),
                f.crc16,
                "{}: frame {i}'s bytes are not the bytes whose CRC-16 the packer \
                 recorded",
                b.name
            );
            assert_eq!(
                u16::from_be_bytes([crc[0], crc[1]]) as u64,
                f.crc16,
                "{}: the footer in the region is not the CRC the packer recorded",
                b.name
            );
        }

        assert!(
            walk.next_frame(&mut left, &mut right, &mut state)
                .expect("end")
                .is_none(),
            "{}: the walk found a frame the table does not name",
            b.name
        );
        assert!(
            walk.at_end(),
            "{}: the walk stopped short of the end of the region",
            b.name
        );
        assert_eq!(
            walk.cursor() as u64,
            region.len() as u64,
            "{}: the frames walked do not tile the region they were given",
            b.name
        );
    }
}

#[test]
fn every_blob_decodes_to_the_pcm_the_reference_decoder_produced() {
    let (blobs, _) = load();
    for b in &blobs {
        let bytes = blob_bytes(&b.name);
        let m = Manifest::parse(bytes).expect("parses");
        let len = FrameBuffers::required_len(&m);
        assert_eq!(len as u64, b.blocksize, "the facade's buffer bound");
        let mut left = vec![0i32; len];
        let mut right = vec![0i32; len];
        let mut bufs = FrameBuffers::new(&mut left, &mut right);
        let mut decoder = Decoder::new(&m).expect("the product path's decoder");

        // One running fold: the whole-stream pin. `Decoder` is the facade the
        // product ROM uses, so this is the C2-shaped read of the asset.
        let mut running = PcmPin::new();
        let mut seen = 0usize;
        while let Some(frame) = decoder.decode_next(&mut bufs).expect("decode") {
            let stereo = !frame.right.is_empty();
            assert_eq!(frame.index, seen, "{}: the facade's frame index", b.name);
            assert_eq!(
                frame.header.blocksize as u64, b.frames[seen].blocksize,
                "{}: facade vs table at frame {seen}",
                b.name
            );
            running.push(stereo, frame.left, frame.right);

            // …and a fresh fold per frame, so a mismatch localizes to a frame
            // instead of merely being noticed somewhere in the stream.
            let mut fresh = PcmPin::new();
            fresh.push(stereo, frame.left, frame.right);
            assert_eq!(
                fresh.values, b.frames[seen].pcm_values,
                "{}: frame {seen} decoded a different number of samples than the \
                 reference decoder emitted for it",
                b.name
            );
            assert_eq!(
                fresh.hash, b.frames[seen].pcm_fnv,
                "{}: frame {seen} does not decode to the samples `flac -d` \
                 produced for it",
                b.name
            );

            // First and last samples of the frame by value. A hash can match
            // with a fold that started one sample late; a boundary cannot.
            let n = frame.left.len() - 1;
            let (want_first, want_last) = (&b.frames[seen].first, &b.frames[seen].last);
            assert_eq!(
                frame.left[0] as i64, want_first[0],
                "{}: frame {seen}'s first left sample",
                b.name
            );
            assert_eq!(
                frame.left[n] as i64, want_last[0],
                "{}: frame {seen}'s last left sample",
                b.name
            );
            if stereo {
                assert_eq!(
                    frame.right[0] as i64, want_first[1],
                    "{}: frame {seen}'s first right sample",
                    b.name
                );
                assert_eq!(
                    frame.right[n] as i64, want_last[1],
                    "{}: frame {seen}'s last right sample — for the mid/side \
                     asset that slot is coded at bps + 1 and decorrelated back",
                    b.name
                );
            }
            seen += 1;
        }
        assert_eq!(seen, b.frames.len(), "{}: how many frames played", b.name);
        assert_eq!(
            running.hash, b.pcm_fnv,
            "{}: the audio played is not the audio `flac -d` made from the \
             source these frames came from",
            b.name
        );
        assert_eq!(
            running.values, b.pcm_values,
            "{}: played sample count",
            b.name
        );
        assert_eq!(
            decoder.sample_position(),
            b.total_samples,
            "{}: the facade's own count of the audio it handed out",
            b.name
        );
        assert!(
            decoder.decode_next(&mut bufs).expect("end").is_none(),
            "{}: the facade played past the end the manifest gives it",
            b.name
        );

        // The table's own boundary rows agree with each other, which is what
        // makes the per-frame pins usable to localize a failure.
        assert_eq!(
            b.pcm_first, b.frames[0].first,
            "{}: the stream's first frame",
            b.name
        );
        assert_eq!(
            b.pcm_last,
            b.frames[b.frames.len() - 1].last,
            "{}: the stream's last frame",
            b.name
        );
    }
}

#[test]
fn one_pcm_three_blobs_and_the_field_that_cannot_tell_them_apart() {
    let (blobs, refusals) = load();
    let independent = "p2_fixed0_stereo_32k_b2048.gfp";
    let midside = "p3_fixed0_midside_32k_b2048.gfp";
    let lpc = "x1_lpc_stereo_32k_b2048.gfp";

    // One source PCM, three encodings. The audio is identical by construction;
    // the frames are not. If that were not true — if the generator had drifted —
    // every claim below would be vacuous, so the pins are checked first.
    let x1 = blob_named(&blobs, lpc);
    let p2 = blob_named(&blobs, independent);
    let p3 = blob_named(&blobs, midside);
    assert_eq!(
        p2.pcm_fnv, p3.pcm_fnv,
        "the mid/side asset must decode to the same audio as the independent one"
    );
    assert_eq!(
        p2.pcm_fnv, x1.pcm_fnv,
        "the LPC asset must decode to the same audio as the FIXED one — same \
         source, only the frames differ"
    );
    assert_ne!(
        p2.frames[0].crc16, x1.frames[0].crc16,
        "the frames must actually differ, or the comparison below proves nothing"
    );
    assert_eq!(decoded_pcm(independent), decoded_pcm(midside));
    assert_eq!(
        decoded_pcm(independent),
        decoded_pcm(lpc),
        "the crate decodes all three to the same samples, correctly. That is the \
         point: correctness was never what distinguished this asset."
    );

    // What the packer's walk saw, as data: six real LPC-4 subframes, and not one
    // FIXED subframe anywhere — which is why the header's max-FIXED-order byte is
    // a true zero. The product-profile assets beside it say the reverse.
    let census = |b: &Blob| -> (u64, u64) {
        let lpc_slots = b
            .slots
            .iter()
            .filter(|s| s.kind == "lpc" && s.order == 4)
            .count() as u64;
        let fixed_slots = b.slots.iter().filter(|s| s.kind == "fixed").count() as u64;
        (lpc_slots, fixed_slots)
    };
    assert_eq!(
        census(x1),
        (6, 0),
        "the packer's walk of the blob it wrote with two guards relaxed: six \
         LPC-4 subframes, no FIXED ones"
    );
    for name in [independent, midside] {
        assert_eq!(
            census(blob_named(&blobs, name)),
            (0, 6),
            "{name}: the product-profile asset stands at 42.48% mean / 42.72% \
             worst of the frame with six FIXED-0 subframes and no LPC ones"
        );
    }

    // And the field a header-based profile check polices is the same on all
    // three — including under a hand-tightened `-l 0`-shaped profile.
    let ms = [(p2, independent), (p3, midside), (x1, lpc)];
    for (b, name) in ms {
        let m = Manifest::parse(blob_bytes(&b.name))
            .unwrap_or_else(|e| panic!("{name}: does not parse: {e:?}"));
        assert_eq!(
            m.max_fixed_order(),
            0,
            "{name}: the header's max FIXED order. For the LPC asset that zero \
             is not a mistake: an all-LPC stream has no FIXED subframe above \
             order 0."
        );
        assert!(
            DEFAULT_PROFILE.validate(&m).is_ok(),
            "{name}: the shipped profile check accepts it"
        );
        assert!(
            m.profile().is_ok(),
            "{name}: the manifest's own check accepts it"
        );
        let fixed_only = EncodeProfile {
            allowed_blocksizes: &[2048],
            max_fixed_order: 0,
            allow_full_lpc: false,
            max_lpc_precision: 0,
            allowed_bits_per_sample: &[16],
        };
        assert!(
            fixed_only.validate(&m).is_ok(),
            "{name}: even a hand-made `-l 0`-shaped profile accepts it, because \
             the field it polices already reads 0 — a manifest cannot answer \
             whether a stream contains LPC subframes, as EncodeProfile::validate \
             itself says. On the decoder's side of the line there is nothing that \
             separates a 42.48%-of-the-frame asset from a 174.14%-of-the-frame \
             one; on the packer's side there is, and the refusal below is it."
        );
    }

    // Which guards were relaxed to write the LPC one — and that the product
    // profile refused the same encode of the same source.
    assert_eq!(x1.decision, "accept");
    assert!(
        !x1.product,
        "and the table records that it is not a product asset"
    );
    assert_eq!(
        x1.relaxations, "allow-lpc,allow-over-budget",
        "two separate guards, both needed: `preflight` refuses to build `-l 4` at \
         a rate where the measured row is already over budget, before reading a \
         byte of frames, and the post-walk cost bar refuses it again. Neither \
         flag implies the other — that is the point of the `relaxations` row."
    );
    assert_eq!(x1.profile_max_lpc_order, 4, "the profile it was built at");
    assert!(x1.allow_lpc && x1.allow_over_budget);
    for b in blobs.iter().filter(|b| b.product) {
        assert_eq!(b.relaxations, "none", "{}: a product blob", b.name);
        assert_eq!(b.profile_max_lpc_order, 0, "{}: built at `-l 0`", b.name);
        assert_eq!(b.decision, "accept", "{}: accepted", b.name);
    }
    assert_eq!(
        blobs.iter().filter(|b| b.product).count(),
        3,
        "three product-shaped assets — mono, independent stereo, mid/side — and \
         one non-product one. Channel count and mid/side vs independent stereo \
         are not product axes: a mono stream with a short final frame is as \
         C2-shaped as a stereo one."
    );

    let refused = refusal(&refusals, "lpc_at_product_profile");
    assert_eq!(refused.exit, 1);
    assert!(!refused.wrote_file, "and it wrote no file");
    for fact in [
        "real LPC subframes",
        "decodes at 174.14% of the frame",
        "1816753 cycles for 2048 samples at the 32768 Hz playback timer",
    ] {
        assert!(
            refused.reason.contains(fact),
            "the refusal of the `-l 4` arm — the same source this table carries \
             as a blob — must state {fact:?}; it said: {}",
            refused.reason
        );
    }
}

#[test]
fn the_refusals_are_on_the_record() {
    let (_, refusals) = load();
    // Each leg's reason, worded by the packer and asserted here against the
    // table: a refusal has to name the property, so whoever reads the message
    // knows what to change. `gen_gafp_fixtures.py --check` re-runs these legs
    // live; this asserts what they printed when the table was generated.
    let rate = refusal(&refusals, "rate_44100_at_32000_target");
    assert_eq!(rate.exit, 1);
    assert!(!rate.wrote_file);
    assert!(
        rate.reason
            .contains("sample rate 44100 Hz is not the target 32000 Hz"),
        "the stream-level fact: {}",
        rate.reason
    );
    assert!(
        rate.reason
            .contains("frame 0 resolves a sample rate of 44100 Hz"),
        "…and the frame-level one, because the walk reads each frame's own rate \
         header instead of trusting STREAMINFO: {}",
        rate.reason
    );

    let depth = refusal(&refusals, "eight_bit_at_16bit");
    assert_eq!(depth.exit, 1);
    assert!(!depth.wrote_file);
    assert!(
        depth
            .reason
            .contains("bits per sample 8 is outside the container's [16]"),
        "the depth fact: {}",
        depth.reason
    );
    assert!(
        depth.reason.contains("no measured decode figure"),
        "…and the walk got far enough to census the subframes and find that an \
         8-bit `-l 0` encode lands on verbatim, which this target has never \
         measured — so the answer is a refusal naming an unmeasured kind, not a \
         guessed figure: {}",
        depth.reason
    );

    for slug in [
        "lpc_at_product_profile",
        "rate_44100_at_32000_target",
        "eight_bit_at_16bit",
    ] {
        refusal(&refusals, slug);
    }
}
